def render_test_snippet(test_name: str, line_number: int):
    # Read the test file and render the block of lines surrounding the failing
    # line. The window is the paragraph (bounded by blank lines) containing the
    # target line, with the target line marked by a `>` gutter.
    file_lines = Path(test_name).read_text(encoding="utf8", errors="backslashreplace").splitlines()
    if not file_lines:
        return []
    total = len(file_lines)
    target_idx = max(0, min(line_number - 1, total - 1))

    start = target_idx
    while start > 0 and file_lines[start - 1].strip() != "":
        start -= 1
    end = target_idx
    while end < total - 1 and file_lines[end + 1].strip() != "":
        end += 1

    # Trim blank lines at the beginning and end of the window.
    while start < end and file_lines[start].strip() == "":
        start += 1
    while end > start and file_lines[end].strip() == "":
        end -= 1

    width = len(str(end + 1))
    rendered = []
    for idx in range(start, end + 1):
        number = str(idx + 1).rjust(width)
        prefix = "  > " if idx == target_idx else "    "
        rendered.append(f"{prefix}{number}  {file_lines[idx]}")
    return rendered


def _format_timeout_seconds(value: str):
    number = float(value)
    if number.is_integer():
        return str(int(number))
    return value


def _collect_progress(stdout: str):
    # Return (started_paths, completed_paths, any_progress) parsed from the
    # `[N/M] (P%): <path>` progress lines. Completed tests carry a `took` suffix.
    started = []
    completed = set()
    any_progress = False
    for raw in strip_ansi(stdout).splitlines():
        line = raw.strip()
        runtime_match = TEST_RUNTIME_PATTERN.match(line)
        if runtime_match:
            any_progress = True
            completed.add(runtime_match.group(1))
            continue
        start_match = PROGRESS_LINE_PATTERN.match(line)
        if start_match:
            any_progress = True
            started.append(start_match.group(1))
    return started, completed, any_progress


def _identify_timed_out_test(stdout: str, batch: list):
    _started, completed, any_progress = _collect_progress(stdout)
    if any_progress:
        for test in batch:
            if test not in completed:
                return test
    return batch[-1] if batch else None


def _find_structured_block(stderr: str):
    # Locate the first structured failure header (`N. <path>:<line>`) and return
    # (header_index, test_path, line_number, stripped_lines) or None.
    lines = strip_ansi(stderr).splitlines()
    for idx, line in enumerate(lines):
        match = STRUCTURED_HEADER_PATTERN.match(line.strip())
        if match:
            return idx, match.group(2), int(match.group(3)), lines
    return None


def _parse_wrong_result(lines: list, header_idx: int):
    description = None
    actual = None
    expected = None
    for idx in range(header_idx, len(lines)):
        stripped = lines[idx].strip()
        if stripped.startswith("Mismatch on row"):
            description = stripped
            for value_idx in range(idx + 1, len(lines)):
                candidate = lines[value_idx].strip()
                if not candidate:
                    continue
                value_match = MISMATCH_VALUE_PATTERN.match(candidate)
                if value_match:
                    actual = value_match.group(1).strip()
                    expected = value_match.group(2).strip()
                break
            break
    return expected, actual, description


def _structured_block_body(lines: list, header_idx: int):
    body = []
    for idx in range(header_idx + 1, len(lines)):
        stripped = lines[idx].strip()
        if stripped.startswith("~~~"):
            break
        if STRUCTURED_HEADER_PATTERN.match(stripped):
            break
        body.append(lines[idx])
    while body and not body[0].strip():
        body.pop(0)
    while body and not body[-1].strip():
        body.pop()
    return body


def _safe_render_snippet(test_name: str, line_number: int):
    try:
